<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { ElMessage, vLoading } from 'element-plus'
import { useOntologyProjection } from './useOntologyProjection'
import { ontologyApi } from '../api/ontologyApi'
import { semanticError, type SemanticError } from '../api/semanticErrors'
import type { Ontology, Revision, Diff, DocumentView, OntologyDocumentSyntax } from '../api/types'
import { useSemanticScope } from '../shared/useSemanticScope'
import './semantic.css'
import OntologyModelWorkbench from './components/OntologyModelWorkbench.vue'
import PublishedKnowledgeApplication from './components/PublishedKnowledgeApplication.vue'
import OntologyLifecycleAction from './components/OntologyLifecycleAction.vue'
import OntologyApplicationsPanel from './components/OntologyApplicationsPanel.vue'
import OntologySourcePanel from './components/OntologySourcePanel.vue'
const { t, locale } = useI18n(); const applicationOpen = ref(false); const route = useRoute(); const router = useRouter(); const { workspace, begin } = useSemanticScope()
const ontologyId = () => String(route.params.id); const ontology = ref<Ontology | null>(null); const revisions = ref<Revision[]>([]); const selectedId = ref(''); const from = ref(''); const to = ref(''); const diff = ref<Diff | null>(null); const busy = ref(false); const error = ref<SemanticError | null>(null)
const tr = (zh: string, en: string) => locale.value.startsWith('zh') ? zh : en
const diffCategory = (value: string) => ({ axioms: tr('模型定义', 'Model definitions'), metadata: t('semantic.metadata'), document: t('semantic.document'), policy: tr('业务规则', 'Business rules') }[value] ?? value)
const diffKey = (value: string) => ({ name: t('semantic.name'), description: tr('说明', 'Description'), source: tr('模型文档', 'Model document'), imports: tr('引用模型', 'Referenced models'), businessPolicy: tr('业务规则', 'Business rules') }[value] ?? value)
const advancedOpen = ref(false)
const focusedAxiomId = ref('')
const workbenchKey = computed(() => `${workspace.currentWorkspaceId ?? ''}:${ontologyId()}:${selectedId.value}`)
const selected = computed(() => revisions.value.find(item => item.id === selectedId.value)); const selectedDocument = computed<DocumentView | undefined>(() => selected.value?.document)
const { data: projectionData, loading: projectionLoading, error: projectionError, reload: reloadProjection } = useOntologyProjection(()=>({workspaceId:workspace.currentWorkspaceId || '',ontologyId:ontologyId(),revisionId:selectedId.value,documentDigest:selectedDocument.value?.documentDigest}))
async function load() { const c = begin(); busy.value = true; error.value = null; try { const [o, list] = await Promise.all([ontologyApi.get(c.id, ontologyId(), c.signal), ontologyApi.revisions(c.id, ontologyId(), c.signal)]); if (c.current()) { ontology.value = o; revisions.value = [...list].sort((a, b) => b.version - a.version); selectedId.value = String(route.query.revision || revisions.value[0]?.id || ''); from.value = revisions.value.some(r => r.id === route.query.from) ? String(route.query.from) : revisions.value[1]?.id ?? ''; to.value = selectedId.value; return true } return false } catch (e) { if (c.current()) error.value = semanticError(e) } finally { if (c.current()) busy.value = false } }
async function createDraft() { if (busy.value || !workspace.can('manage:ontology')) return; const c = begin(); busy.value = true; try { await ontologyApi.createDraft(c.id, ontologyId(), selectedId.value || null, c.signal); if (c.current()) await router.push({ name: 'OntologyEditor', params: { id: ontologyId() } }) } catch (e) { if (c.current()) error.value = semanticError(e) } finally { if (c.current()) busy.value = false } }
async function compare() { if (!to.value || from.value === to.value) return; const c = begin(); busy.value = true; diff.value = null; try { const value = await ontologyApi.diff(c.id, ontologyId(), from.value || null, to.value, c.signal); if (c.current()) diff.value = value } catch (e) { if (c.current()) error.value = semanticError(e) } finally { if (c.current()) busy.value = false } }
async function setAvailability() { if (!selected.value || !workspace.can('publish:ontology')) return; const c = begin(); busy.value = true; try { const value = await ontologyApi.availability(c.id, ontologyId(), selected.value.id, !selected.value.availableForNewBindings, c.signal); if (c.current()) revisions.value = revisions.value.map(item => item.id === value.id ? value : item) } catch (e) { if (c.current()) error.value = semanticError(e) } finally { if (c.current()) busy.value = false } }
async function exportDocument(syntax: OntologyDocumentSyntax) { if (!selected.value) return; const c = begin(); busy.value = true; try { const bytes = await ontologyApi.exportDocument(c.id, ontologyId(), selected.value.id, syntax, c.signal); const url = URL.createObjectURL(new Blob([bytes], { type: syntax === 'RDF_XML' ? 'application/rdf+xml' : 'text/plain;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = `ontology-v${selected.value.version}.${syntax === 'RDF_XML' ? 'rdf' : 'ofn'}`; link.click(); URL.revokeObjectURL(url) } catch (e) { if (c.current()) ElMessage.error((e as Error).message) } finally { if (c.current()) busy.value = false } }
async function exportPackage() { if (!selected.value) return; const c = begin(); busy.value = true; try { const value = await ontologyApi.packageForRevision(c.id, ontologyId(), selected.value.id, c.signal); const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json;charset=utf-8' })); const link = globalThis.document.createElement('a'); link.href = url; link.download = `${value.name || ontology.value?.name || 'ontology'}-v${selected.value.version}.json`; link.click(); URL.revokeObjectURL(url) } catch (e) { if (c.current()) error.value = semanticError(e) } finally { if (c.current()) busy.value = false } }
function inspectAxiom(axiomId: string) {
  focusedAxiomId.value = axiomId
  void nextTick(() => {
    const panel = globalThis.document.querySelector<HTMLElement>('[data-ontology-source-panel]')
    if (panel) {
      panel.focus({ preventScroll: true })
      if (typeof panel.scrollIntoView === 'function') panel.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
  })
}
function clearAxiomFocus() { focusedAxiomId.value = '' }
watch(() => [workspace.currentWorkspaceId, ontologyId(), selectedId.value], () => { focusedAxiomId.value = '' }, { flush: 'sync' })
watch(() => [workspace.currentWorkspaceId, ontologyId(), route.query.revision, route.query.from], async () => {
  applicationOpen.value = false; diff.value = null; const loaded = await load()
  if (!loaded) return
  if (route.query.from && from.value === route.query.from && to.value !== from.value) await compare()
}, { immediate: true })
</script>
<template><section class="semantic-page"><header class="semantic-header"><div><h1>{{ ontology?.name || t('semantic.history') }}</h1><p class="semantic-muted">{{ ontology?.description }}</p></div><div class="semantic-actions"><OntologyLifecycleAction v-if="ontology" :ontology="ontology" @updated="load" /><el-button @click="router.push({ name: 'OntologyList' })">{{ t('semantic.back') }}</el-button><el-button v-if="ontology?.hasDraft" @click="router.push({ name: 'OntologyEditor', params: { id: ontologyId() } })">{{ t('semantic.openDraft') }}</el-button><el-button v-if="workspace.can('manage:ontology') && !ontology?.hasDraft && !ontology?.archived" type="primary" @click="createDraft">{{ t('semantic.newDraft') }}</el-button></div></header><el-alert v-if="ontology?.archived" type="info" :closable="false" :title="locale.startsWith('zh') ? '模型已归档，历史与已有应用保留。' : 'Archived model: history and existing applications are retained.'" /><el-alert v-if="error" type="error" :title="error.code" :description="error.message" :closable="false" /><div v-loading="busy" class="semantic-panel"><el-table :data="revisions" highlight-current-row @row-click="selectedId = $event.id"><el-table-column :label="t('semantic.version')" width="110"><template #default="{ row }"><el-button link type="primary" @click="selectedId = row.id">v{{ row.version }}</el-button></template></el-table-column><el-table-column prop="name" :label="t('semantic.name')" /><el-table-column prop="publicationNote" :label="t('semantic.publicationNote')" /><el-table-column :label="tr('定义数', 'Definitions')" width="100"><template #default="{ row }">{{ row.document?.axioms.length ?? 0 }}</template></el-table-column><el-table-column :label="t('semantic.availability')" width="150"><template #default="{ row }">{{ row.availableForNewBindings ? t('semantic.available') : t('semantic.unavailable') }}</template></el-table-column></el-table></div><div v-if="selected" class="semantic-panel"><header class="semantic-header"><div><h2>v{{ selected.version }} · {{ selected.name }}</h2><p class="semantic-muted">{{ selectedDocument?.ontologyIri }} · {{ selectedDocument?.documentDigest }}</p></div><div class="semantic-actions"><el-button v-if="workspace.can('publish:ontology') && !ontology?.archived" type="primary" :disabled="busy" @click="applicationOpen = true">{{ locale.startsWith('zh') ? '应用到知识库' : 'Apply to knowledge base' }}</el-button><el-button :disabled="busy" @click="exportDocument('FUNCTIONAL')">{{ t('semantic.exportFunctional', 'Export Functional') }}</el-button><el-button :disabled="busy" @click="exportDocument('RDF_XML')">{{ t('semantic.exportRdfXml', 'Export RDF/XML') }}</el-button><el-button :disabled="busy" @click="exportPackage">{{ t('semantic.exportTemplate') }}</el-button><el-button v-if="workspace.can('publish:ontology') && !ontology?.archived" :disabled="busy" @click="setAvailability">{{ selected.availableForNewBindings ? t('semantic.disableAvailability') : t('semantic.enableAvailability') }}</el-button></div></header><OntologyModelWorkbench :key="workbenchKey" :projection="projectionData?.projection" :projection-loading="projectionLoading" :projection-error="projectionError" @reload-projection="reloadProjection" :axioms="selectedDocument?.axioms || []" @advanced="advancedOpen = true" @inspect-axiom="inspectAxiom" /><details :open="advancedOpen" class="ontology-draft-graph"><summary>{{ t('semantic.advancedDocument', '高级 OWL 文档') }}</summary><el-table :data="selectedDocument?.axioms" :empty-text="t('semantic.emptyAxioms', 'No axioms')"><el-table-column prop="axiomType" :label="tr('类型', 'Type')" width="190" /><el-table-column prop="rendering" :label="tr('OWL 表达式', 'OWL expression')" min-width="600" show-overflow-tooltip /><el-table-column :label="tr('关联标识', 'Referenced identifiers')" min-width="300"><template #default="{ row }">{{ row.signatureIris.join(', ') }}</template></el-table-column></el-table></details></div><div v-if="revisions.length" class="semantic-panel"><h3>{{ t('semantic.compare') }}</h3><div class="semantic-toolbar"><el-select v-model="from" :aria-label="tr('原版本', 'From')"><el-option value="" :label="tr('空白基线', 'Baseline')" /><el-option v-for="revision in revisions" :key="revision.id" :value="revision.id" :label="'v' + revision.version" /></el-select><span>→</span><el-select v-model="to" :aria-label="tr('目标版本', 'To')"><el-option v-for="revision in revisions" :key="revision.id" :value="revision.id" :label="'v' + revision.version" /></el-select><el-button :disabled="busy || !to || from === to" @click="compare">{{ t('semantic.compare') }}</el-button></div><el-table v-if="diff" :data="diff.changes" :empty-text="t('semantic.noChanges')"><el-table-column :label="t('semantic.change')"><template #default="{ row }">{{ t('semantic.changes.' + row.kind, row.kind) }}</template></el-table-column><el-table-column :label="t('semantic.category')"><template #default="{ row }">{{ diffCategory(row.category) }}</template></el-table-column><el-table-column :label="tr('变更内容', 'Changed content')"><template #default="{ row }">{{ diffKey(row.key) }}</template></el-table-column></el-table></div><OntologyApplicationsPanel :ontology-id="ontologyId()" :target="selected" :archived="ontology?.archived" /><OntologySourcePanel v-if="selected && selectedDocument" data-ontology-source-panel tabindex="-1" :ontology-id="ontologyId()" :revision-id="selected.id" :focused-axiom-id="focusedAxiomId" :axioms="selectedDocument.axioms" :projection="projectionData?.projection" :can-manage="false" :can-review="workspace.can('publish:ontology')&&!ontology?.archived" @clear-focus="clearAxiomFocus" @modeling-task="router.push({ name: 'OntologyEditor', params: { id: ontologyId() }, query: { taskId: $event } })" /><PublishedKnowledgeApplication v-if="applicationOpen && selected" v-model="applicationOpen" :revision="selected" /></section></template>

<style scoped>
.semantic-header > div { min-width: 0; max-width: 100%; }
.semantic-header .semantic-muted { overflow-wrap: anywhere; }
</style>
